import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { identifyHandler } from "../handlers/identifyHandler";
import type { ApiError } from "../runtime/client";
import type { IdentificationRequest } from "../types/IdentificationRequest";

type Data = Awaited<ReturnType<typeof identifyHandler>>;
type Vars = IdentificationRequest;

export function useIdentify(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => identifyHandler(vars),
    ...options,
  });
}
